#!/usr/bin/env python3
"""Regression tests for the title generated by Minima and authored Markdown."""

from html.parser import HTMLParser
import unittest
from pathlib import Path
import sys


class ArticleHeadings(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.articles = []
        self.article_stack = []
        self.div_content_stack = []
        self.heading_text = None

    @staticmethod
    def classes(attrs):
        return set(dict(attrs).get("class", "").split())

    def handle_starttag(self, tag, attrs):
        classes = self.classes(attrs)
        if tag == "article" and "post" in classes:
            article = {"title_headings": [], "content_headings": []}
            self.articles.append(article)
            self.article_stack.append(article)
        if tag == "div":
            self.div_content_stack.append("post-content" in classes)
        if tag == "h1" and self.article_stack:
            heading = {"classes": classes, "text": ""}
            article = self.article_stack[-1]
            if "post-content" in classes or any(self.div_content_stack):
                article["content_headings"].append(heading)
            else:
                article["title_headings"].append(heading)
            self.heading_text = heading

    def handle_endtag(self, tag):
        if tag == "h1":
            self.heading_text = None
        elif tag == "div" and self.div_content_stack:
            self.div_content_stack.pop()
        elif tag == "article" and self.article_stack:
            self.article_stack.pop()

    def handle_data(self, data):
        if self.heading_text is not None:
            self.heading_text["text"] += data


def rendered_article_headings(source):
    parser = ArticleHeadings()
    parser.feed(source)
    parser.close()
    return parser.articles


def has_duplicate_h1(article):
    return len(article["title_headings"]) + len(article["content_headings"]) > 1


def check_site(site_root):
    site_root = Path(site_root)
    if not site_root.is_dir():
        return [f"built site directory does not exist: {site_root}"]
    failures = []
    for path in sorted(site_root.rglob("*.html")):
        articles = rendered_article_headings(path.read_text(errors="replace"))
        for article in articles:
            heading_count = len(article["title_headings"]) + len(article["content_headings"])
            if heading_count != 1:
                failures.append(f"{path.relative_to(site_root)} has {heading_count} article H1 headings")
    target = site_root / "10-frontend/10.1-javascript/01-execution-and-scope/INDEX.html"
    if target.is_file():
        articles = rendered_article_headings(target.read_text(errors="replace"))
        if len(articles) != 1 or [h["text"].strip() for h in articles[0]["content_headings"]] != ["Execution & Scope — JavaScript"]:
            failures.append("Execution & Scope INDEX must render its authored title exactly once")
    else:
        failures.append("built Execution & Scope INDEX is missing")
    return failures


class RenderedHeadingTests(unittest.TestCase):
    def test_authored_heading_replaces_theme_title(self):
        html = ('<article class="post"><header><h1 class="post-title">'
                'Generated title</h1></header><div class="post-content">'
                '<h1 id="authored">Authored title</h1></div></article>')
        article, = rendered_article_headings(html)
        self.assertTrue(has_duplicate_h1(article), "the pre-fix rendering contains both headings")
        corrected, = rendered_article_headings(
            '<article class="post"><div class="post-content">'
            '<h1 id="authored">Authored title</h1></div></article>')
        self.assertFalse(has_duplicate_h1(corrected))

    def test_page_without_authored_heading_keeps_theme_title(self):
        html = ('<article class="post"><header><h1 class="post-title">'
                'Fallback title</h1></header><div class="post-content"><p>Text</p>'
                '</div></article>')
        article, = rendered_article_headings(html)
        self.assertEqual([h["text"] for h in article["title_headings"]], ["Fallback title"])
        self.assertEqual(article["content_headings"], [])

    def test_nested_content_div_does_not_end_content_tracking(self):
        html = ('<article class="post"><div class="post-content"><div><h1>'
                'Authored title</h1></div></div></article>')
        article, = rendered_article_headings(html)
        self.assertEqual([h["text"] for h in article["content_headings"]], ["Authored title"])


if __name__ == "__main__":
    if len(sys.argv) == 2:
        problems = check_site(sys.argv[1])
        if problems:
            print("\n".join(problems))
            raise SystemExit(1)
        print(f"rendered heading check passed for {sys.argv[1]}")
    else:
        unittest.main()
